<?php
header('Content-Type:text/html;charset=UTF-8');
$ROOT=realpath(__DIR__);$SKIP=['.git','node_modules','vendor'];
function blocked($p){global $SKIP;foreach($SKIP as $s)if(preg_match('#(^|/)'.preg_quote($s,'#').'(/|$)#',$p))return true;return false;}
function scan($root){$files=[];$dirs=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));foreach($it as $f){$p=str_replace('\\','/',substr($f->getPathname(),strlen($root)+1));if(!$p||blocked($p)||$p==='site-wire-live.php')continue;if($f->isDir())$dirs[]=$p;else $files[$p]=$f->getSize();}ksort($files);$refs=[];$rx=['/\b(?:require|require_once|include|include_once)\s*\(?\s*[\'\"]([^\'\"]+)[\'\"]/i','/\b(?:import|export)\s+(?:[^\'\";]+?\s+from\s+)?[\'\"]([^\'\"]+)[\'\"]/i','/\b(?:src|href)\s*=\s*[\'\"]([^\'\"]+)[\'\"]/i'];foreach($files as $p=>$size){if($size>700000||!preg_match('/\.(php|js|mjs|jsx|ts|tsx|css|scss|html|htm|json|xml|svg|yml|yaml|ini|conf|md)$/i',$p))continue;$s=@file_get_contents($root.'/'.$p);if($s===false)continue;foreach($rx as $re){preg_match_all($re,$s,$m);foreach(array_unique($m[1]??[]) as $v){$v=trim(preg_replace('/[#?].*$/','',$v));if(!$v||preg_match('/^(https?:|data:|mailto:|javascript:|#|\/\/)/i',$v))continue;$base=dirname($p);$c=ltrim(str_replace('\\','/',($v[0]==='/'?$v:$base.'/'.$v)),'/');foreach([$c,$c.'.php',$c.'.js',$c.'.css',$c.'.json',$c.'.html',$c.'/index.php',$c.'/index.html'] as $z)if(isset($files[$z])){$refs[]=['from'=>$p,'to'=>$z];break;}}}}return['files'=>array_keys($files),'dirs'=>$dirs,'refs'=>$refs,'time'=>date('H:i:s')];}
$D=scan($ROOT);if(isset($_GET['pulse'])){header('Content-Type:application/json');echo json_encode(['ok'=>1,'time'=>date('H:i:s')]);exit;}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartToolz — Relationship Manager</title><style>
*{box-sizing:border-box}html,body{margin:0;height:100%;overflow:hidden;background:#070d12;color:#dce8ed;font-family:Inter,system-ui,sans-serif}#map{width:100%;height:100%;display:block}.top{position:fixed;top:18px;left:22px;right:22px;display:flex;justify-content:space-between;z-index:3;pointer-events:none}.brand{font-weight:800;font-size:18px}.brand b{color:#55dfce}.sub{font:8px monospace;color:#58717b;margin-top:4px}.stats{display:flex;gap:6px}.stat,.search,.panel,.btn{background:#0a151be8;border:1px solid #31505a;border-radius:8px}.stat{padding:7px 10px}.stat small{display:block;color:#59727b;font:7px monospace}.stat strong{font:10px monospace}.live{color:#58dfb6}.search{position:fixed;top:72px;left:22px;width:240px;padding:9px 11px;color:white;outline:0;font:9px monospace;z-index:3}.panel{position:fixed;display:none;right:22px;top:72px;width:310px;padding:14px;z-index:4}.panel.show{display:block}.panel button{float:right;background:none;border:0;color:#71868e;font-size:18px}.ey{font:7px monospace;color:#58737c;letter-spacing:1px}.panel h3{margin:7px 0 2px}.path{font:8px monospace;color:#62ddd1;word-break:break-all}.rels{margin-top:10px;font:8px monospace;color:#83969d;max-height:280px;overflow:auto;line-height:1.7}.tools{position:fixed;left:22px;bottom:18px;z-index:3;display:flex;gap:6px}.btn{padding:8px 12px;color:#9eb3ba;font:8px monospace;cursor:pointer}.hint{position:fixed;bottom:20px;left:50%;transform:translateX(-50%);font:8px monospace;color:#526b75}.node{cursor:pointer}.group{fill:#0c191e;stroke:#2c535a}.folder{fill:#111529;stroke:#514780}.file{fill:#091319;stroke:#29424a}.wire{fill:none;stroke:#31515a;stroke-width:1}.dep{fill:none;stroke:#4c8c8c;stroke-width:1.3;stroke-dasharray:6 8}.active{stroke:#55dfce!important;stroke-width:2!important}.label{font:8px monospace;fill:#8da3aa}@media(max-width:700px){.top{left:10px;right:10px}.brand{font-size:15px}.sub{display:none}.stats .stat:nth-child(n+3){display:none}.search{left:10px;top:62px;width:190px}.panel{left:10px;right:10px;top:62px;width:auto}.tools{left:10px;bottom:10px}.hint{display:none}}
</style></head><body>
<div class="top"><div><div class="brand"><b>◇</b> SmartToolz Relationship Manager</div><div class="sub">ACTUAL FILES • ACTUAL REFERENCES • SIMPLE VIEW</div></div><div class="stats"><div class="stat"><small>FILES</small><strong id="fc"><?php echo count($D['files']);?></strong></div><div class="stat"><small>RELATIONS</small><strong id="ec"><?php echo count($D['refs']);?></strong></div><div class="stat"><small>SERVER</small><strong class="live" id="state">LIVE</strong></div></div></div>
<input class="search" id="search" placeholder="Search file…"><svg id="map" xmlns="http://www.w3.org/2000/svg"></svg><div class="panel" id="panel"><button id="close">×</button><div class="ey">SELECTED FILE</div><h3 id="pn"></h3><div class="path" id="pp"></div><div class="rels" id="rr"></div></div><div class="tools"><button class="btn" id="home">HOME</button><button class="btn" id="refresh">RESCAN</button></div><div class="hint">Click folder • click file • drag • wheel zoom</div>
<script>
const D=<?php echo json_encode($D,JSON_UNESCAPED_SLASHES);?>,svg=document.getElementById('map'),NS='http://www.w3.org/2000/svg';let zoom=.9,px=innerWidth/2,py=innerHeight/2,open=null,selected=null,hover=null,drag=0,lx=0,ly=0;
const E=s=>String(s).replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]));
function topFolders(){return [...new Set(D.files.map(f=>f.split('/')[0]))].sort()}
function filesIn(p){return D.files.filter(f=>f.startsWith(p+'/')&&!f.slice(p.length+1).includes('/'))}
function dirsIn(p){return D.dirs.filter(d=>d.startsWith(p+'/')&&!d.slice(p.length+1).includes('/'))}
function draw(){svg.innerHTML='';const W=innerWidth,H=innerHeight,roots=topFolders();let nodes=[];if(!open){roots.forEach((r,i)=>{const a=i/Math.max(1,roots.length)*Math.PI*2,n={id:r,type:'folder',name:r+'/',x:W/2+Math.cos(a)*Math.min(W*.3,390),y:H/2+Math.sin(a)*Math.min(H*.3,230),w:170,h:34};nodes.push(n)});}else{nodes.push({id:open,type:'root',name:open+'/',x:W/2,y:H/2,w:190,h:40});dirsIn(open).forEach((d,i)=>nodes.push({id:d,type:'folder',name:d.split('/').pop()+'/',x:W/2+240,y:H/2+(i-(dirsIn(open).length-1)/2)*48,w:160,h:32}));filesIn(open).forEach((f,i)=>nodes.push({id:f,type:'file',name:f.split('/').pop(),x:W/2-250,y:H/2+(i-Math.min(filesIn(open).length,22)/2)*34,w:150,h:28}));}
const by=new Map(nodes.map(n=>[n.id,n])),g=document.createElementNS(NS,'g');if(open){const root=by.get(open);nodes.filter(n=>n!==root).forEach(n=>{const p=document.createElementNS(NS,'path'),a=pos(root),b=pos(n),m=(a.x+b.x)/2;p.setAttribute('d',`M${a.x} ${a.y} C${m} ${a.y} ${m} ${b.y} ${b.x} ${b.y}`);p.setAttribute('class','wire');g.appendChild(p)});D.refs.forEach(r=>{if(by.has(r.from)&&by.has(r.to)){const a=pos(by.get(r.from)),b=pos(by.get(r.to)),p=document.createElementNS(NS,'path'),m=(a.x+b.x)/2;p.setAttribute('d',`M${a.x} ${a.y} C${m} ${a.y} ${m} ${b.y} ${b.x} ${b.y}`);p.setAttribute('class',(r.from===selected||r.to===selected)?'dep active':'dep');g.appendChild(p)}})}svg.appendChild(g);const ng=document.createElementNS(NS,'g');nodes.forEach(n=>{const p=pos(n),q=document.createElementNS(NS,'g'),r=document.createElementNS(NS,'rect');r.setAttribute('x',p.x-n.w/2);r.setAttribute('y',p.y-n.h/2);r.setAttribute('width',n.w);r.setAttribute('height',n.h);r.setAttribute('rx',7);r.setAttribute('class',n.type==='root'?'group':n.type==='folder'?'folder':'file');if(n.id===selected||n.id===hover)r.classList.add('active');q.appendChild(r);const t=document.createElementNS(NS,'text');t.setAttribute('x',p.x);t.setAttribute('y',p.y+3);t.setAttribute('text-anchor','middle');t.setAttribute('class','label');t.textContent=n.name;q.appendChild(t);q.onclick=e=>{e.stopPropagation();select(n)};ng.appendChild(q)});svg.appendChild(ng)}
function pos(n){return{x:n.x*zoom+(px-innerWidth/2),y:n.y*zoom+(py-innerHeight/2)}}
function select(n){if(!n){open=null;selected=null;document.getElementById('panel').classList.remove('show');draw();return}selected=n.id;if(n.type==='folder'||n.type==='root')open=n.id;document.getElementById('panel').classList.add('show');document.getElementById('pn').textContent=n.name;document.getElementById('pp').textContent=n.id;const r=D.refs.filter(v=>v.from===n.id||v.to===n.id);document.getElementById('rr').innerHTML='<b>'+r.length+' direct relationships</b><br>'+r.map(v=>E(v.from)+' → '+E(v.to)).join('<br>');draw()}
function hit(x,y){let best=null;const roots=topFolders();if(!open){roots.forEach(r=>{const i=roots.indexOf(r),a=i/Math.max(1,roots.length)*Math.PI*2,n={id:r,type:'folder',x:innerWidth/2+Math.cos(a)*Math.min(innerWidth*.3,390),y:innerHeight/2+Math.sin(a)*Math.min(innerHeight*.3,230),w:170,h:34};const p=pos(n);if(Math.abs(x-p.x)<85&&Math.abs(y-p.y)<17)best=n})}else{draw();}return best}
svg.addEventListener('pointerdown',e=>{drag=1;lx=e.clientX;ly=e.clientY});addEventListener('pointermove',e=>{if(drag){px+=e.clientX-lx;py+=e.clientY-ly;lx=e.clientX;ly=e.clientY;draw()}});addEventListener('pointerup',e=>{if(drag){drag=0;const dx=e.clientX-lx,dy=e.clientY-ly;if(Math.abs(dx)+Math.abs(dy)<4){const r=hit(e.clientX,e.clientY);if(r)select(r)}}});svg.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.5,Math.min(1.8,zoom*(e.deltaY<0?1.1:.9)));draw()},{passive:false});document.getElementById('close').onclick=()=>select(null);document.getElementById('home').onclick=()=>{open=null;selected=null;zoom=.9;px=innerWidth/2;py=innerHeight/2;draw()};document.getElementById('refresh').onclick=()=>location.reload();document.getElementById('search').oninput=e=>{const q=e.target.value.toLowerCase();const f=D.files.find(v=>v.toLowerCase().includes(q));if(f){open=f.split('/')[0];selected=f;document.getElementById('panel').classList.add('show');document.getElementById('pn').textContent=f.split('/').pop();document.getElementById('pp').textContent=f;draw()}};draw();
</script></body></html>